{
  "description": "PostBoot_Debian_Login_Wifi_Root_SSH_Enablement",
  "attempts": 2,
  "retryFromLastFailedGroup": false,
  "groups": [
    {
      "name": "Debian_Login_via_Python",
      "attempts": 1,
      "steps": [
        {
          "step": "runPythonScript",
          "description": "Handle Debian serial login and set new Debian password",
          "input": [
            {
              "path": "TaaS/TaaS_Generic_On_Device/serialport_debianlogin.py#head",
              "skipInputParam": false,
              "timeOutInSec": 900
            }
          ]
        }
      ]
    },
    {
      "name": "Wifi_Root_SSH_Configuration",
      "attempts": 1,
      "steps": [
        {
          "step": "sleep",
          "description": "Wait for shell prompt after Python login",
          "input": [
            { "sleepTimeInSec": 5 }
          ]
        },
        {
          "step": "writeToSerialPort",
          "description": "Switch to root using sudo",
          "input": [
            {
              "command": "sudo -i",
              "portIndex": 0,
              "appendNewLine": true
            }
          ]
        },
        {
          "step": "sleep",
          "description": "Wait for sudo password prompt",
          "input": [
            { "sleepTimeInSec": 2 }
          ]
        },
        {
          "step": "writeToSerialPort",
          "description": "Enter sudo password (Debian)",
          "input": [
            {
              "command": "Debian",
              "portIndex": 0,
              "appendNewLine": true
            }
          ]
        },
        {
          "step": "sleep",
          "description": "Wait for root shell",
          "input": [
            { "sleepTimeInSec": 5 }
          ]
        },
        {
          "step": "writeToSerialPort",
          "description": "Connect to Wi-Fi",
          "input": [
            {
              "command": "nmcli dev wifi connect Hydra password K5x48Vz3",
              "portIndex": 0,
              "appendNewLine": true
            }
          ]
        },
        {
          "step": "sleep",
          "description": "Allow Wi-Fi connection to stabilize",
          "input": [
            { "sleepTimeInSec": 20 }
          ]
        },
        {
          "step": "writeToSerialPort",
          "description": "Update apt repositories",
          "input": [
            {
              "command": "apt update",
              "portIndex": 0,
              "appendNewLine": true
            }
          ]
        },
        {
          "step": "sleep",
          "description": "Wait for apt update to complete",
          "input": [
            { "sleepTimeInSec": 60 }
          ]
        },
        {
          "step": "writeToSerialPort",
          "description": "Install OpenSSH server",
          "input": [
            {
              "command": "apt install openssh-server -y",
              "portIndex": 0,
              "appendNewLine": true
            }
          ]
        },
        {
          "step": "sleep",
          "description": "Wait for OpenSSH installation",
          "input": [
            { "sleepTimeInSec": 30 }
          ]
        },
        {
          "step": "writeToSerialPort",
          "description": "Set root password",
          "input": [
            {
              "command": "passwd root",
              "portIndex": 0,
              "appendNewLine": true
            }
          ]
        },
        {
          "step": "sleep",
          "description": "Wait for new root password prompt",
          "input": [
            { "sleepTimeInSec": 2 }
          ]
        },
        {
          "step": "writeToSerialPort",
          "description": "Enter new root password",
          "input": [
            {
              "command": "oelinux123",
              "portIndex": 0,
              "appendNewLine": true
            }
          ]
        },
        {
          "step": "sleep",
          "description": "Wait for confirm password prompt",
          "input": [
            { "sleepTimeInSec": 2 }
          ]
        },
        {
          "step": "writeToSerialPort",
          "description": "Confirm root password",
          "input": [
            {
              "command": "oelinux123",
              "portIndex": 0,
              "appendNewLine": true
            }
          ]
        },
        {
          "step": "sleep",
          "description": "Wait for root password to take effect",
          "input": [
            { "sleepTimeInSec": 10 }
          ]
        },
        {
          "step": "writeToSerialPort",
          "description": "Enable SSH root login",
          "input": [
            {
              "command": "echo \"PermitRootLogin yes\" | tee -a /etc/ssh/sshd_config",
              "portIndex": 0,
              "appendNewLine": true
            }
          ]
        },
        {
          "step": "sleep",
          "description": "Wait between SSH config updates",
          "input": [
            { "sleepTimeInSec": 10 }
          ]
        },
        {
          "step": "writeToSerialPort",
          "description": "Enable SSH password authentication",
          "input": [
            {
              "command": "echo \"PasswordAuthentication yes\" | tee -a /etc/ssh/sshd_config",
              "portIndex": 0,
              "appendNewLine": true
            }
          ]
        },
        {
          "step": "sleep",
          "description": "Wait before restarting SSH",
          "input": [
            { "sleepTimeInSec": 10 }
          ]
        },
        {
          "step": "writeToSerialPort",
          "description": "Restart and enable SSH service",
          "input": [
            {
              "command": "systemctl restart ssh",
              "portIndex": 0,
              "appendNewLine": true
            },
            {
              "command": "systemctl enable --now ssh",
              "portIndex": 0,
              "appendNewLine": true
            }
          ]
        }
      ]
    }
  ]
}
